"""Single-page admin interface served by aiohttp at /admin."""

ADMIN_HTML = r'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nexus — управление магазином</title><style>
:root{color-scheme:dark;--bg:#0b1020;--card:#141c31;--line:#2a3856;--text:#ecf3ff;--muted:#97a8c5;--accent:#7bb5ff;--bad:#ff7586}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px Inter,system-ui,sans-serif}.login{width:min(420px,calc(100% - 32px);margin:14vh auto;padding:28px;border:1px solid var(--line);border-radius:20px;background:var(--card)}h1,h2,h3,p{margin-top:0}input,textarea,select,button{font:inherit}input,textarea,select{width:100%;padding:11px;border:1px solid var(--line);border-radius:9px;background:#0c1324;color:var(--text)}textarea{min-height:115px;resize:vertical}button{padding:10px 14px;border:0;border-radius:9px;background:var(--accent);color:#07101e;font-weight:750;cursor:pointer}button.secondary{background:#273551;color:var(--text)}button.danger{background:var(--bad)}label{display:grid;gap:6px;color:var(--muted);font-size:13px}.error{color:#ff9da9;min-height:20px}.layout{display:grid;grid-template-columns:230px 1fr;min-height:100vh}.side{padding:24px 14px;border-right:1px solid var(--line);background:#0e1527}.side strong{display:block;margin:0 10px 22px;font-size:19px}.side button{display:block;width:100%;margin:4px 0;text-align:left;background:transparent;color:var(--muted)}.side button.active{background:#213555;color:white}.main{max-width:1280px;padding:32px;margin:auto;width:100%}.view{display:none}.view.active{display:block}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{padding:18px;border:1px solid var(--line);border-radius:14px;background:var(--card)}.card span{display:block;color:var(--muted);font-size:12px}.card strong{display:block;margin-top:9px;font-size:26px}.toolbar{display:flex;gap:10px;align-items:center;justify-content:space-between;margin:18px 0}.toolbar input{max-width:310px}table{width:100%;border-collapse:collapse}th,td{padding:11px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--muted);font-size:12px}td.actions{white-space:nowrap}td.actions button{padding:7px 9px;margin-right:4px;font-size:12px}.modal{position:fixed;inset:0;z-index:3;display:none;place-items:center;padding:16px;background:#030713bb}.modal.open{display:grid}.modal-box{width:min(640px,100%);max-height:94vh;overflow:auto;padding:22px;border:1px solid var(--line);border-radius:16px;background:var(--card)}.form{display:grid;gap:13px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.check{display:flex;align-items:center;gap:8px}.check input{width:auto}.stock-meta{color:var(--muted);font-size:13px}.empty{padding:28px;text-align:center;color:var(--muted)}@media(max-width:760px){.layout{grid-template-columns:1fr}.side{display:flex;gap:3px;overflow:auto;padding:12px;border-right:0;border-bottom:1px solid var(--line)}.side strong{display:none}.side button{width:auto;white-space:nowrap}.main{padding:20px 14px}.cards{grid-template-columns:1fr 1fr}.table-wrap{overflow:auto}.form-row{grid-template-columns:1fr}}
</style><body><section id="login" class="login"><h1>Nexus Admin</h1><p>Введите секрет из переменной <code>ADMIN_SECRET</code> на Hostless.</p><form id="loginForm" class="form"><label>Секретный ключ<input id="secret" type="password" autocomplete="current-password" required></label><button>Войти</button><div id="loginError" class="error"></div></form></section><section id="app" hidden class="layout"><aside class="side"><strong>Nexus Admin</strong><button data-view="dashboard" class="active">Обзор</button><button data-view="products">Товары</button><button data-view="categories">Категории</button><button data-view="customers">Покупатели</button><button data-view="orders">Покупки</button><button id="logout">Выйти</button></aside><main class="main"><section id="dashboard" class="view active"><h1>Обзор магазина</h1><div class="cards" id="metrics"></div><div class="panel" style="margin-top:18px"><h2>Топ категорий</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Категория</th><th>Продаж</th><th>Выручка</th></tr></thead><tbody id="tops"></tbody></table></div></div></section><section id="products" class="view"><div class="toolbar"><h1>Товары</h1><button onclick="openProduct()">+ Добавить товар</button></div><div class="panel table-wrap"><table><thead><tr><th>Название</th><th>Категория</th><th>Цена</th><th>Автовыдача</th><th>Статус</th><th></th></tr></thead><tbody id="productRows"></tbody></table></div></section><section id="categories" class="view"><div class="toolbar"><h1>Категории</h1><button onclick="openCategory()">+ Добавить категорию</button></div><div class="panel table-wrap"><table><thead><tr><th>Название</th><th>Порядок</th><th>Статус</th><th></th></tr></thead><tbody id="categoryRows"></tbody></table></div></section><section id="customers" class="view"><h1>Покупатели</h1><div class="toolbar"><input id="customerSearch" placeholder="Поиск по username"><button onclick="loadCustomers()">Найти</button></div><div class="panel table-wrap"><table><thead><tr><th>Username</th><th>Имя / Telegram ID</th><th>Баланс</th><th>Покупок</th><th></th></tr></thead><tbody id="customerRows"></tbody></table></div></section><section id="orders" class="view"><h1>Список покупок</h1><div class="panel table-wrap"><table><thead><tr><th>Дата</th><th>Покупатель</th><th>Товар</th><th>Сумма</th><th>Статус</th></tr></thead><tbody id="orderRows"></tbody></table></div></section></main></section><div id="modal" class="modal"><div class="modal-box" id="modalBox"></div></div><script>
let token=localStorage.getItem('nexus_admin_token')||'',categories=[],products=[]; const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));const money=v=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB'}).format(Number(v));
async function api(path,opt={}){let r=await fetch('/api/admin'+path,{...opt,headers:{'Content-Type':'application/json','X-Admin-Token':token,...opt.headers}});if(r.status===401){logout();throw Error('Сессия истекла')}let d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка запроса');return d}
function show(view){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));({dashboard:loadDashboard,products:loadProducts,categories:loadCategories,customers:loadCustomers,orders:loadOrders}[view])()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view)); $('logout').onclick=logout;function logout(){token='';localStorage.removeItem('nexus_admin_token');$('app').hidden=true;$('login').hidden=false}
$('loginForm').onsubmit=async e=>{e.preventDefault();try{let d=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({secret:$('secret').value})}).then(r=>r.json());if(!d.token)throw Error(d.error||'Неверный ключ');token=d.token;localStorage.setItem('nexus_admin_token',token);$('login').hidden=true;$('app').hidden=false;loadDashboard()}catch(err){$('loginError').textContent=err.message}};
function closeModal(){ $('modal').classList.remove('open') } $('modal').onclick=e=>{if(e.target===$('modal'))closeModal()};function modal(html){$('modalBox').innerHTML=html;$('modal').classList.add('open')}
async function loadDashboard(){let d=await api('/dashboard');$('metrics').innerHTML=[['Всего заработано',money(d.revenue)],['Заработано сегодня',money(d.today_revenue)],['Оплаченных покупок',d.orders],['Посещений сегодня',d.today_visits]].map(x=>`<div class="card"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');$('tops').innerHTML=d.top_categories.length?d.top_categories.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name)}</td><td>${x.sales}</td><td>${money(x.revenue)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">Пока нет продаж</td></tr>'}
async function loadCategories(){categories=await api('/categories');$('categoryRows').innerHTML=categories.length?categories.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.sort_order}</td><td>${x.is_active?'Активна':'Скрыта'}</td><td class="actions"><button class="secondary" onclick="openCategory(${x.id})">Изменить</button></td></tr>`).join(''):'<tr><td colspan="4" class="empty">Категорий пока нет</td></tr>'}
async function loadProducts(){categories=await api('/categories');products=await api('/products');$('productRows').innerHTML=products.length?products.map(x=>`<tr><td><b>${esc(x.name)}</b><br><small>${esc(x.description)}</small></td><td>${esc(x.category_name||'—')}</td><td>${money(x.price)}</td><td>${x.stock_count} шт.</td><td>${x.is_active?'Активен':'Скрыт'}</td><td class="actions"><button class="secondary" onclick="openProduct(${x.id})">Изменить</button><button class="secondary" onclick="openStock(${x.id})">Выдача</button><button class="danger" onclick="deleteProduct(${x.id})">Удалить</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Добавьте первый товар</td></tr>'}
function openCategory(id){let x=categories.find(x=>x.id===id)||{name:'',sort_order:categories.length,is_active:true};modal(`<h2>${id?'Изменить':'Новая'} категория</h2><form class="form" onsubmit="saveCategory(event,${id||'null'})"><label>Название<input name="name" value="${esc(x.name)}" required></label><label>Порядок показа<input name="sort_order" type="number" value="${x.sort_order}"></label><label class="check"><input name="is_active" type="checkbox" ${x.is_active?'checked':''}> Показывать в магазине</label><button>Сохранить</button><button type="button" class="secondary" onclick="closeModal()">Отмена</button></form>`)}
async function saveCategory(e,id){e.preventDefault();let f=new FormData(e.target);await api('/categories'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify({name:f.get('name'),sort_order:+f.get('sort_order'),is_active:f.has('is_active')})});closeModal();loadCategories()}
function openProduct(id){let x=products.find(x=>x.id===id)||{name:'',description:'',price:'0',category_id:'',is_active:true};modal(`<h2>${id?'Изменить':'Новый'} товар</h2><form class="form" onsubmit="saveProduct(event,${id||'null'})"><label>Название<input name="name" value="${esc(x.name)}" required></label><label>Описание<textarea name="description">${esc(x.description)}</textarea></label><div class="form-row"><label>Цена, ₽<input name="price" type="number" min="0" step="0.01" value="${x.price}" required></label><label>Категория<select name="category_id"><option value="">Без категории</option>${categories.map(c=>`<option value="${c.id}" ${String(c.id)===String(x.category_id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><label class="check"><input name="is_active" type="checkbox" ${x.is_active?'checked':''}> Активный товар</label><button>Сохранить</button><button type="button" class="secondary" onclick="closeModal()">Отмена</button></form>`)}
async function saveProduct(e,id){e.preventDefault();let f=new FormData(e.target);await api('/products'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify({name:f.get('name'),description:f.get('description'),price:f.get('price'),category_id:f.get('category_id')?+f.get('category_id'):null,is_active:f.has('is_active')})});closeModal();loadProducts()}
async function deleteProduct(id){if(confirm('Удалить товар и его невыданные позиции?')){await api('/products/'+id,{method:'DELETE'});loadProducts()}}
async function openStock(id){let x=products.find(x=>x.id===id),d=await api('/products/'+id+'/stock');modal(`<h2>Автовыдача: ${esc(x.name)}</h2><p class="stock-meta">Каждая строка — отдельный ключ, аккаунт или инструкция. Выданные позиции сохраняются и не будут удалены.</p><form class="form" onsubmit="saveStock(event,${id})"><label>Список для выдачи<textarea name="items" placeholder="ключ-1&#10;ключ-2">${d.filter(i=>!i.is_issued).map(i=>esc(i.payload)).join('\n')}</textarea></label><p class="stock-meta">В наличии: ${d.filter(i=>!i.is_issued).length}; уже выдано: ${d.filter(i=>i.is_issued).length}</p><button>Заменить список в наличии</button><button type="button" class="secondary" onclick="closeModal()">Отмена</button></form>`)}
async function saveStock(e,id){e.preventDefault();let f=new FormData(e.target);await api('/products/'+id+'/stock',{method:'PUT',body:JSON.stringify({items:f.get('items').split(/\r?\n/).filter(Boolean)})});closeModal();loadProducts()}
async function loadCustomers(){let d=await api('/customers?q='+encodeURIComponent($('customerSearch').value));$('customerRows').innerHTML=d.length?d.map(x=>`<tr><td>${x.username?'@'+esc(x.username):'—'}</td><td>${esc(x.first_name)}<br><small>${x.telegram_id}</small></td><td>${money(x.balance)}</td><td>${x.purchases}</td><td class="actions">${x.username?`<button onclick="openGrant('${esc(x.username)}')">Выдать баланс</button>`:''}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Покупатели появятся после запуска бота</td></tr>'}
function openGrant(username){modal(`<h2>Выдать баланс @${username}</h2><form class="form" onsubmit="grant(event,'${username}')"><label>Сумма, ₽<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Причина<input name="reason" value="Выдано администратором"></label><button>Зачислить</button><button type="button" class="secondary" onclick="closeModal()">Отмена</button></form>`)}async function grant(e,u){e.preventDefault();let f=new FormData(e.target);await api('/customers/'+encodeURIComponent(u)+'/balance',{method:'POST',body:JSON.stringify({amount:f.get('amount'),reason:f.get('reason')})});closeModal();loadCustomers()}
async function loadOrders(){let d=await api('/orders');$('orderRows').innerHTML=d.length?d.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('ru-RU')}</td><td>${x.username?'@'+esc(x.username):esc(x.first_name||'—')}</td><td>${esc(x.product_name||'Удалённый товар')}</td><td>${money(x.amount)}</td><td>${esc(x.status)}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Покупок пока нет</td></tr>'}
if(token){$('login').hidden=true;$('app').hidden=false;loadDashboard()}
</script></body></html>'''
